import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { io } from 'socket.io-client';
import { Activity, AlertTriangle, ArrowLeftRight, Bot, CheckCircle2, ChevronLeft, ChevronRight, Clock3, Download, ExternalLink, Link2, Loader2, Pause, Play, Plus, RefreshCw, Search, ShieldCheck, Square, Trash2, Upload, UserRound, Users, Wifi, WifiOff, X } from 'lucide-react';
import { API, authFetch } from '../utils/api';
import { useToast } from '../components/ui/ToastProvider';
import { cn } from '@/utils/cn';
import TelegramWordImportPanel from '../components/TelegramWordImportPanel';

type Account = {
  id: string; name: string; phone_number?: string; username?: string; status?: string;
  automation_role: 'SEARCH_ROLE' | 'JOIN_ROLE'; automation_enabled?: boolean;
  last_activity_at?: string; last_operation_at?: string; operation_count?: number;
  error_count?: number; last_error?: string; stopped_at?: string; stop_reason?: string; worker_state?: string; connection_state?: string; last_heartbeat_at?: string; next_allowed_operation_at?: string;
};
type LinkRow = { id: string; normalized_url: string; original_url: string; telegram_identifier?: string; link_type: string; status: string; join_status: string; source_account_name?: string; first_seen_at: string; last_seen_at: string; last_error?: string; joined_by_accounts?: string[] };
type EventRow = { id: string; event_type: string; status?: string; created_at: string; payload?: Record<string, any> };
type Dashboard = { accounts: Account[]; searchAccounts: Account[]; joinAccounts: Account[]; links: LinkRow[]; events: EventRow[]; latestJobId?: string | null; workers: Array<{ accountId: string; status: string; ready?: boolean; role?: string; lastCheck?: string; linksFound?: number; error?: string; workerId?: string; connectionState?: string }>; stats: Record<string, number> };
type JobData = { job?: any; operations?: any[]; events?: EventRow[]; stats?: Record<string, number>; progress?: number } | null;
type JoinSettings = { minDelaySeconds: number; maxDelaySeconds: number; maxRetries: number; retryBackoffSeconds: number; strategy: string; selectedSearchAccountIds: string[]; selectedAccountIds: string[]; selectedLinkIds: string[]; updatedAt?: string | null };

const emptyDashboard: Dashboard = { accounts: [], searchAccounts: [], joinAccounts: [], links: [], events: [], workers: [], stats: {} };
const roleLabel = { SEARCH_ROLE: 'بحث واكتشاف فقط', JOIN_ROLE: 'انضمام فقط' };
const eventLabel: Record<string, string> = { link_discovered: 'اكتشاف رابط جديد', link_duplicate: 'تحديث رابط مكرر', link_imported: 'استيراد رابط', job_created: 'إنشاء مهمة انضمام', operation_completed: 'اكتمال عملية انضمام', operation_failed: 'فشل عملية انضمام', operation_retry: 'تأجيل لإعادة المحاولة', operation_recovered: 'استعادة عملية', operation_recovered_as_already_member: 'استعادة كعضو مسبقًا', discovery_completed: 'اكتمال البحث', discovery_recovered: 'استعادة البحث', job_paused: 'إيقاف مؤقت للمهمة', job_resumed: 'استئناف المهمة', job_stopped: 'إيقاف المهمة', account_role_changed: 'تغيير دور الحساب' };

function json<T>(value: T): string { return JSON.stringify(value); }
async function read(response: Response) { const body = await response.text(); try { return body ? JSON.parse(body) : {}; } catch { throw new Error(`استجابة غير صالحة من الخادم (${response.status})`); } }
function date(value?: string) { return value ? new Date(value).toLocaleString('ar-SA', { dateStyle: 'short', timeStyle: 'short' }) : '—'; }
function ago(value?: string) { if (!value) return 'لا يوجد نشاط'; const seconds = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 1000)); return seconds < 60 ? `منذ ${seconds} ث` : seconds < 3600 ? `منذ ${Math.floor(seconds / 60)} د` : `منذ ${Math.floor(seconds / 3600)} س`; }
function statusTone(value?: string) { return value === 'JOINED' || value === 'SUCCESS' || value === 'ALREADY_MEMBER' || value === 'CONNECTED' || value === 'READY' ? 'text-emerald-300 bg-emerald-400/10 border-emerald-400/20' : value === 'FAILED' || value === 'ERROR' || value === 'AUTH_REQUIRED' ? 'text-rose-300 bg-rose-400/10 border-rose-400/20' : value === 'PROCESSING' || value === 'RETRY' || value === 'RUNNING' || value === 'CONNECTING' ? 'text-sky-300 bg-sky-400/10 border-sky-400/20' : 'text-amber-300 bg-amber-400/10 border-amber-400/20'; }
function statusLabel(value?: string) { return ({ NEW: 'جديد', PENDING: 'جاهز للانضمام', PROCESSING: 'قيد التنفيذ', JOINED: 'تم الانضمام', PARTIALLY_JOINED: 'منضم جزئيًا', FAILED: 'فشل', ARCHIVED: 'مؤرشف', QUEUED: 'في الطابور', RETRY: 'إعادة محاولة', SUCCESS: 'نجح', ALREADY_MEMBER: 'عضو مسبقًا', SKIPPED: 'تم التخطي', SKIPPED_DUPLICATE: 'مكرر عالميًا — تم التخطي', RESERVED: 'محجوز لمعالجة أخرى', BLOCKED: 'محظور', INVALID: 'غير صالح', CONNECTED: 'متصل', READY: 'جاهز', RUNNING: 'يعمل', CONNECTING: 'جارٍ الاتصال', DISCONNECTED: 'غير متصل', DEGRADED: 'متدهور', ERROR: 'خطأ', AUTH_REQUIRED: 'يتطلب مصادقة', JOIN_PENDING: 'طلب انضمام معلّق', NOT_VERIFIED: 'غير موثق' } as Record<string, string>)[value || ''] || value || 'غير معروف'; }

function Pill({ value }: { value?: string }) { return <span className={cn('inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] font-bold', statusTone(value))}><span className="h-1.5 w-1.5 rounded-full bg-current" />{statusLabel(value)}</span>; }
function Metric({ label, value, hint, icon: Icon, tone }: { label: string; value: string | number; hint: string; icon: any; tone: string }) { return <div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs text-[var(--text-muted)]">{label}</span><span className={cn('rounded-xl p-2', tone)}><Icon className="h-4 w-4" /></span></div><p className="mt-3 text-2xl font-black text-[var(--text-primary)]">{value}</p><p className="mt-1 text-[11px] text-[var(--text-muted)]">{hint}</p></div>; }

export default function JoinAutomationView() {
  const { addToast } = useToast();
  const [dashboard, setDashboard] = useState<Dashboard>(emptyDashboard);
  const [job, setJob] = useState<JobData>(null);
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState<string | null>(null);
  const [selectedSearch, setSelectedSearch] = useState<string[]>([]);
  const [selectedJoin, setSelectedJoin] = useState<string[]>([]);
  const [selectedLinks, setSelectedLinks] = useState<string[]>([]);
  const [minDelay, setMinDelay] = useState(120);
  const [maxDelay, setMaxDelay] = useState(150);
  const [maxRetries, setMaxRetries] = useState(1);
  const [strategy, setStrategy] = useState('smart');
  const [settingsReady, setSettingsReady] = useState(false);
  const [settingsSaveState, setSettingsSaveState] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const settingsSaveTimer = useRef<number | null>(null);
  const [query, setQuery] = useState('');
  const [activeJobId, setActiveJobId] = useState<string | null>(null);
  const [health, setHealth] = useState<any>(null);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [importOpen, setImportOpen] = useState(false);
  const [importContent, setImportContent] = useState('');
  const [importSource, setImportSource] = useState('');
  const [globalLookup, setGlobalLookup] = useState('');
  const [globalResult, setGlobalResult] = useState<any>(null);
  const [globalLoading, setGlobalLoading] = useState(false);
  const [membershipReview, setMembershipReview] = useState<any>(null);
  const [keepAccountId, setKeepAccountId] = useState('');
  const [membershipLoading, setMembershipLoading] = useState(false);
  const searchRequestKey = useRef(crypto.randomUUID());
  const createJobRequestKey = useRef(crypto.randomUUID());
  const importRequestKey = useRef(crypto.randomUUID());

  const notify = useCallback((message: string, type: 'success' | 'warning' | 'error' = 'success') => addToast({ title: message, type }), [addToast]);
  const fetchDashboard = useCallback(async () => { try { const response = await authFetch(`${API}/telegram/join-automation-v2/dashboard`); const envelope = await read(response); const data = envelope.data || envelope; if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر تحميل أتمتة Telegram'); setDashboard(data); setActiveJobId(data.latestJobId || null); setSelectedSearch(current => current.filter(id => data.searchAccounts.some((a: Account) => a.id === id))); setSelectedJoin(current => current.filter(id => data.joinAccounts.some((a: Account) => a.id === id))); } catch (error: any) { notify(error.message || 'فشل تحميل البيانات', 'error'); } finally { setLoading(false); } }, [notify]);
  const fetchSettings = useCallback(async () => { try { const response = await authFetch(`${API}/telegram/join-automation-v2/settings`); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر تحميل إعدادات أتمتة Telegram'); const data = envelope.data as JoinSettings; setMinDelay(Number(data.minDelaySeconds || 120)); setMaxDelay(Number(data.maxDelaySeconds || 150)); setMaxRetries(Number(data.maxRetries ?? 1)); setStrategy(data.strategy || 'smart'); setSelectedSearch(Array.isArray(data.selectedSearchAccountIds) ? data.selectedSearchAccountIds.map(String) : []); setSelectedJoin(Array.isArray(data.selectedAccountIds) ? data.selectedAccountIds.map(String) : []); setSelectedLinks(Array.isArray(data.selectedLinkIds) ? data.selectedLinkIds.map(String) : []); setSettingsReady(true); } catch (error: any) { setSettingsReady(false); notify(error.message || 'فشل تحميل إعدادات الأتمتة', 'error'); } }, [notify]);
  const fetchLinks = useCallback(async () => { try { const response = await authFetch(`${API}/telegram/join-automation-v2/links?page=${page}&pageSize=50&search=${encodeURIComponent(query)}`); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر تحميل الروابط'); const data = envelope.data || {}; setDashboard(current => ({ ...current, links: data.items || [] })); setTotalPages(Math.max(1, data.totalPages || 1)); } catch (error: any) { notify(error.message || 'فشل تحميل الروابط', 'error'); } }, [page, query, notify]);
  const fetchHealth = useCallback(async () => { try { const response = await authFetch(`${API}/telegram/join-automation-v2/health`); const envelope = await read(response); if (response.ok && envelope.success) setHealth(envelope.data || envelope); } catch {} }, []);
  async function lookupGlobal() { if (!globalLookup.trim()) return notify('أدخل رابط Telegram للبحث', 'warning'); setGlobalLoading(true); try { const response = await authFetch(`${API}/telegram/join-automation-v2/global-status?url=${encodeURIComponent(globalLookup.trim())}`); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || 'تعذر فحص الرابط العالمي'); setGlobalResult(envelope.data || envelope); } catch (error: any) { notify(error.message || 'فشل فحص الرابط العالمي', 'error'); } finally { setGlobalLoading(false); } }
  async function reviewMemberships() { setMembershipLoading(true); try { const suffix = keepAccountId ? `?keepAccountId=${encodeURIComponent(keepAccountId)}` : ''; const response = await authFetch(`${API}/telegram/join-automation-v2/membership-review${suffix}`); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || 'تعذر مراجعة العضويات'); setMembershipReview(envelope.data || envelope); notify(`اكتملت المراجعة: ${envelope.data?.duplicateGroups || 0} مجموعات مكررة`, 'success'); } catch (error: any) { notify(error.message || 'فشل مراجعة العضويات', 'error'); } finally { setMembershipLoading(false); } }
  async function cleanupMemberships() { if (!membershipReview?.duplicateGroups) return notify('لا توجد مجموعات مكررة للتنظيف', 'warning'); if (!window.confirm('سيتم الخروج من الحسابات الزائدة فقط، مع إبقاء العضوية في الحساب المختار. هل تريد المتابعة؟')) return; setMembershipLoading(true); try { const response = await authFetch(`${API}/telegram/join-automation-v2/membership-review/cleanup`, { method: 'POST', body: json({ keepAccountId: keepAccountId || null, confirm: true }) }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || 'تعذر تنفيذ التنظيف'); setMembershipReview(envelope.data || envelope); notify(`تم الخروج من ${envelope.data?.left || 0} عضوية مكررة`, 'success'); } catch (error: any) { notify(error.message || 'فشل تنظيف العضويات', 'error'); } finally { setMembershipLoading(false); } }
  const fetchJob = useCallback(async () => { if (!activeJobId) return; try { const response = await authFetch(`${API}/telegram/join-automation-v2/jobs/${activeJobId}`); const envelope = await read(response); if (response.ok && envelope.success) setJob(envelope.data || envelope); } catch {} }, [activeJobId]);
  useEffect(() => { fetchDashboard(); fetchHealth(); fetchSettings(); const timer = window.setInterval(() => { fetchDashboard(); fetchHealth(); }, 10000); return () => window.clearInterval(timer); }, [fetchDashboard, fetchHealth, fetchSettings]);
  const persistSettings = useCallback(async () => { if (!settingsReady) return; setSettingsSaveState('saving'); try { const response = await authFetch(`${API}/telegram/join-automation-v2/settings`, { method: 'PATCH', body: json({ minDelaySeconds: minDelay, maxDelaySeconds: maxDelay, maxRetries, strategy, selectedSearchAccountIds: selectedSearch, selectedAccountIds: selectedJoin, selectedLinkIds: selectedLinks }) }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر حفظ إعدادات الأتمتة'); setSettingsSaveState('saved'); } catch (error: any) { setSettingsSaveState('error'); notify(error.message || 'فشل حفظ إعدادات الأتمتة', 'error'); } }, [settingsReady, minDelay, maxDelay, maxRetries, strategy, selectedSearch, selectedJoin, selectedLinks, notify]);
  useEffect(() => { if (!settingsReady) return; if (settingsSaveTimer.current) window.clearTimeout(settingsSaveTimer.current); settingsSaveTimer.current = window.setTimeout(() => { persistSettings(); }, 650); return () => { if (settingsSaveTimer.current) window.clearTimeout(settingsSaveTimer.current); }; }, [settingsReady, minDelay, maxDelay, maxRetries, strategy, selectedSearch, selectedJoin, selectedLinks, persistSettings]);
  useEffect(() => { fetchLinks(); }, [fetchLinks]);
  useEffect(() => { if (!activeJobId) { setJob(null); return; } fetchJob(); const timer = window.setInterval(fetchJob, 4000); return () => window.clearInterval(timer); }, [activeJobId, fetchJob]);
  useEffect(() => { const socket = io(); const refresh = () => { fetchDashboard(); fetchJob(); }; ['link_discovered', 'link_duplicate', 'job_created', 'operation_completed', 'operation_failed', 'operation_retry', 'job_paused', 'job_resumed', 'job_stopped'].forEach(event => socket.on(`telegram:join-automation:${event}`, refresh)); return () => { socket.off(); socket.disconnect(); }; }, [fetchDashboard, fetchJob]);

  const workerFor = (id: string) => dashboard.workers.find(worker => String(worker.accountId) === String(id));
  const isJoinWorkerReady = (account: Account) => { const worker = workerFor(account.id); const status = String(worker?.status || '').toLowerCase(); return account.automation_enabled !== false && account.status === 'connected' && (worker?.ready === true || (status === 'running' && String(worker?.connectionState || '').toUpperCase() === 'CONNECTED')); };
  const filteredLinks = useMemo(() => dashboard.links, [dashboard.links]);
  const eligibleSearch = dashboard.searchAccounts.filter(a => a.automation_enabled !== false);
  const eligibleJoin = dashboard.joinAccounts.filter(isJoinWorkerReady);
  const toggle = (setter: (value: (current: string[]) => string[]) => void, id: string) => setter(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);

  async function changeRole(account: Account, role: Account['automation_role']) { setWorking(`role:${account.id}`); try { const response = await authFetch(`${API}/telegram/join-automation-v2/accounts/${account.id}/role`, { method: 'PATCH', body: json({ role, enabled: true }) }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر تغيير دور الحساب'); notify(`تم تعيين ${account.name} إلى ${roleLabel[role]}`); await fetchDashboard(); } catch (error: any) { notify(error.message || 'فشل تغيير دور الحساب', 'error'); } finally { setWorking(null); } }
  async function searchNow() { if (!selectedSearch.length) return notify('حدد حساب بحث واحدًا على الأقل', 'warning'); setWorking('search'); try { const response = await authFetch(`${API}/telegram/join-automation-v2/search`, { method: 'POST', body: json({ accountIds: selectedSearch, requestId: searchRequestKey.current }) }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر بدء البحث'); notify('تم إنشاء مهمة بحث durable في الخلفية؛ ستتحدث النتائج تلقائيًا', 'success'); searchRequestKey.current = crypto.randomUUID(); await fetchDashboard(); } catch (error: any) { notify(error.message || 'فشل بدء البحث', 'error'); } finally { setWorking(null); } }
  async function createJob(allPending = false) { const accountIds = selectedJoin.length ? selectedJoin : eligibleJoin.length === 1 ? [eligibleJoin[0].id] : []; if (!accountIds.length) return notify(eligibleJoin.length ? 'حدد حساب الانضمام من قائمة الحسابات الجاهزة أو اضغط تحديد الجاهز' : 'لا يوجد حساب JOIN_ROLE متصل وWorker الخاص به جاهز؛ انتظر ظهور حالة RUNNING ثم حدّث الصفحة', 'warning'); if (!allPending && !selectedLinks.length) return notify('حدد روابط Telegram مؤهلة أو استخدم زر كل الروابط الجاهزة', 'warning'); if (minDelay < 30 || maxDelay < minDelay) return notify('الفاصل يجب أن يبدأ من 30 ثانية والحد الأدنى لا يتجاوز الأعلى', 'warning'); setWorking('job'); try { const response = await authFetch(`${API}/telegram/join-automation-v2/jobs`, { method: 'POST', body: json({ accountIds, linkIds: allPending ? [] : selectedLinks, allPending, requestId: createJobRequestKey.current, settings: { minDelaySeconds: minDelay, maxDelaySeconds: maxDelay, maxRetries, strategy } }) }); const envelope = await read(response); const data = envelope.data || {}; if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر إنشاء مهمة الانضمام'); setActiveJobId(data.job?.id); setSelectedLinks([]); createJobRequestKey.current = crypto.randomUUID(); notify(data.idempotent ? 'تمت إعادة نفس المهمة بأمان دون تكرار' : `تم إنشاء مهمة حقيقية من ${data.totalOperations} عملية في Outbox/Queue`); await fetchDashboard(); } catch (error: any) { notify(error.message || 'فشل إنشاء المهمة', 'error'); } finally { setWorking(null); } }
  async function controlJob(status: 'PAUSED' | 'RUNNING' | 'STOPPED') { if (!activeJobId) return; setWorking(`job:${status}`); try { const response = await authFetch(`${API}/telegram/join-automation-v2/jobs/${activeJobId}`, { method: 'PATCH', body: json({ status }) }); const envelope = await read(response); const data = envelope.data || {}; if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر تحديث المهمة'); setJob(data); notify(status === 'STOPPED' ? 'تم إيقاف المهمة وحفظ السجل' : status === 'PAUSED' ? 'تم إيقاف المهمة مؤقتًا' : 'تم استئناف المهمة'); } catch (error: any) { notify(error.message || 'فشل التحكم بالمهمة', 'error'); } finally { setWorking(null); } }
  async function deleteLink(linkId: string) { if (!window.confirm('سيتم حذف الرابط من قائمة الروابط المؤهلة مع الاحتفاظ بسجل العمليات. هل تريد المتابعة؟')) return; setWorking(`link:${linkId}`); try { const response = await authFetch(`${API}/telegram/join-automation-v2/links/${linkId}/archive`, { method: 'PATCH', body: '{}' }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر حذف الرابط'); notify('تم حذف الرابط من القائمة مع الاحتفاظ بسجل عملياته'); await fetchDashboard(); await fetchLinks(); } catch (error: any) { notify(error.message || 'فشل حذف الرابط', 'error'); } finally { setWorking(null); } }
  async function deleteAllLinks() { const count = Number(dashboard.stats?.total || 0); if (!count) return notify('لا توجد روابط مؤهلة للحذف', 'warning'); if (!window.confirm(`سيتم حذف جميع الروابط المؤهلة (${count}) مع الاحتفاظ بسجل العمليات. هل تريد المتابعة؟`)) return; setWorking('links:all'); try { const response = await authFetch(`${API}/telegram/join-automation-v2/links`, { method: 'DELETE', body: '{}' }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر حذف جميع الروابط'); setSelectedLinks([]); notify(`تم حذف ${Number(envelope.data?.count || count)} رابط من القائمة`); await fetchDashboard(); await fetchLinks(); } catch (error: any) { notify(error.message || 'فشل حذف جميع الروابط', 'error'); } finally { setWorking(null); } }
  async function exportData(entity: 'links' | 'operations' | 'jobs' | 'events') { try { const response = await authFetch(`${API}/telegram/join-automation-v2/export?entity=${entity}&format=json`); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر التصدير'); const data = envelope.data; const blob = new Blob([data.content], { type: 'application/json;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = data.filename; anchor.click(); URL.revokeObjectURL(url); notify(`تم تصدير ${entity} مع احترام الملكية`); } catch (error: any) { notify(error.message || 'فشل التصدير', 'error'); } }
  async function importLinks() { if (!importSource) return notify('اختر حساب SEARCH_ROLE كمصدر للاستيراد', 'warning'); if (!importContent.trim()) return notify('ألصق روابط Telegram أولًا', 'warning'); setWorking('import'); try { const response = await authFetch(`${API}/telegram/join-automation-v2/links/import`, { method: 'POST', body: json({ sourceAccountId: importSource, content: importContent, format: 'txt', requestId: importRequestKey.current }) }); const envelope = await read(response); if (!response.ok || !envelope.success) throw new Error(envelope.error?.message || envelope.error || 'تعذر استيراد الروابط'); notify(`تم الاستيراد: ${envelope.data.saved} جديد، ${envelope.data.duplicates} مكرر، ${envelope.data.invalid} غير صالح`); setImportContent(''); setImportOpen(false); importRequestKey.current = crypto.randomUUID(); await fetchDashboard(); await fetchLinks(); } catch (error: any) { notify(error.message || 'فشل الاستيراد', 'error'); } finally { setWorking(null); } }

  return <main dir="rtl" className="mx-auto w-full max-w-[1600px] space-y-5 p-4 pb-10 sm:p-6">
    <TelegramWordImportPanel onSaved={async () => { await fetchDashboard(); await fetchLinks(); }} />
    <header className="overflow-hidden rounded-3xl border border-cyan-400/20 bg-gradient-to-br from-cyan-500/10 via-[var(--bg-surface)] to-violet-500/10 p-6 shadow-[var(--shadow-card)] sm:p-8">
      <div className="flex flex-wrap items-start justify-between gap-5"><div className="flex items-start gap-4"><div className="rounded-2xl bg-cyan-400/15 p-3 text-cyan-300"><Bot className="h-8 w-8" /></div><div><p className="text-xs font-bold tracking-[0.18em] text-cyan-300">TELEGRAM AUTOMATION / CONTROL PLANE</p><h1 className="mt-2 text-2xl font-black sm:text-3xl">أتمتة الانضمام لروابط تيليجرام</h1><p className="mt-2 max-w-3xl text-sm leading-7 text-[var(--text-muted)]">محرك حقيقي لاكتشاف روابط Telegram من حسابات مخصصة للبحث، ثم تنفيذ الانضمام بحسابات مستقلة عبر Queue قابلة للاستئناف. لا يتم استخدام حساب البحث للانضمام أو حساب الانضمام للبحث.</p></div></div><a href="/telegram" className="inline-flex items-center gap-2 rounded-xl border border-cyan-400/25 bg-cyan-400/10 px-4 py-2.5 text-xs font-black text-cyan-200 transition hover:bg-cyan-400/20"><Plus className="h-4 w-4" />إضافة حساب Telegram</a></div>
      <div className="mt-6 flex flex-wrap items-center gap-2 text-xs text-[var(--text-muted)]"><span className="inline-flex items-center gap-2 rounded-full border border-emerald-400/20 bg-emerald-400/10 px-3 py-1.5 text-emerald-200"><ShieldCheck className="h-3.5 w-3.5" />عزل SEARCH_ROLE / JOIN_ROLE مفعل</span><span className="inline-flex items-center gap-2 rounded-full border border-violet-400/20 bg-violet-400/10 px-3 py-1.5 text-violet-200"><Activity className="h-3.5 w-3.5" />البيانات من الخادم والـ Queue</span><span className="inline-flex items-center gap-2 rounded-full border border-amber-400/20 bg-amber-400/10 px-3 py-1.5 text-amber-200"><Clock3 className="h-3.5 w-3.5" />احترام الفواصل وحدود Telegram</span></div><div className="mt-4 flex flex-wrap items-center gap-2 text-[11px]"><span className={cn('rounded-full border px-3 py-1.5', health?.status === 'healthy' ? 'border-emerald-400/20 bg-emerald-400/10 text-emerald-200' : 'border-amber-400/20 bg-amber-400/10 text-amber-200')}>النظام: {health?.status === 'healthy' ? 'سليم' : health?.status === 'degraded' ? 'متدهور' : health?.status === 'unhealthy' ? 'غير سليم' : 'جارٍ التحقق'}</span><span className="rounded-full border border-[var(--border-default)] bg-[var(--bg-surface)] px-3 py-1.5 text-[var(--text-muted)]">PostgreSQL: {health?.components?.postgresql || '—'}</span><span className="rounded-full border border-[var(--border-default)] bg-[var(--bg-surface)] px-3 py-1.5 text-[var(--text-muted)]">Redis: {health?.components?.redis || '—'}</span><span className="rounded-full border border-[var(--border-default)] bg-[var(--bg-surface)] px-3 py-1.5 text-[var(--text-muted)]">Queue: {health?.components?.queue || '—'}</span><button type="button" onClick={() => { fetchDashboard(); fetchHealth(); fetchLinks(); }} className="inline-flex items-center gap-1 rounded-full border border-[var(--border-default)] px-3 py-1.5 font-bold text-[var(--text-secondary)]"><RefreshCw className="h-3 w-3" />تحديث النظام</button></div>
    </header>

    <section className="grid grid-cols-2 gap-3 md:grid-cols-4 xl:grid-cols-8"><Metric label="إجمالي الروابط" value={dashboard.stats.total || 0} hint={`${dashboard.stats.new || 0} جديدة`} icon={Link2} tone="bg-cyan-400/10 text-cyan-300" /><Metric label="جاهزة للانضمام" value={dashboard.stats.pending || 0} hint="لم تنفذ بعد" icon={ArrowLeftRight} tone="bg-amber-400/10 text-amber-300" /><Metric label="تم الانضمام" value={dashboard.stats.joined || 0} hint="بتأكيد Telegram" icon={CheckCircle2} tone="bg-emerald-400/10 text-emerald-300" /><Metric label="فاشلة" value={dashboard.stats.failed || 0} hint="تحتاج مراجعة" icon={AlertTriangle} tone="bg-rose-400/10 text-rose-300" /><Metric label="حسابات البحث" value={eligibleSearch.length} hint="SEARCH_ROLE" icon={Search} tone="bg-sky-400/10 text-sky-300" /><Metric label="حسابات الانضمام" value={eligibleJoin.length} hint="متصلة وجاهزة" icon={UserRound} tone="bg-violet-400/10 text-violet-300" /><Metric label="العمليات" value={dashboard.stats.operations || 0} hint={`${dashboard.stats.successfulOperations || 0} ناجحة`} icon={Activity} tone="bg-indigo-400/10 text-indigo-300" /><Metric label="مهام نشطة" value={dashboard.stats.activeJobs || 0} hint="تعمل في الخلفية" icon={Bot} tone="bg-orange-400/10 text-orange-300" /></section>

    <section className="rounded-3xl border border-violet-400/20 bg-violet-500/5 p-5 shadow-[var(--shadow-card)]"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-violet-300"><ShieldCheck className="h-5 w-5" /><h2 className="text-lg font-black">Global Deduplication Registry</h2></div><p className="mt-2 text-xs leading-6 text-[var(--text-muted)]">مصدر حقيقة مركزي يمنع إرسال طلب انضمام إذا كان الرابط محجوزًا أو تم الانضمام إليه سابقًا بواسطة أي حساب.</p></div><div className="flex w-full max-w-xl gap-2"><input value={globalLookup} onChange={event => setGlobalLookup(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') lookupGlobal(); }} placeholder="https://t.me/example" dir="ltr" className="min-w-0 flex-1 rounded-xl border border-[var(--border-default)] bg-[var(--bg-surface)] px-3 py-2.5 text-xs" /><button type="button" onClick={lookupGlobal} disabled={globalLoading} className="inline-flex items-center gap-2 rounded-xl bg-violet-500 px-4 py-2.5 text-xs font-black text-white disabled:opacity-50">{globalLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}فحص عالمي</button></div></div>{globalResult && <div className="mt-4 grid gap-3 text-xs md:grid-cols-4"><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-3"><span className="text-[var(--text-muted)]">الحالة</span><p className="mt-1 font-black text-violet-200">{statusLabel(globalResult.status)}</p></div><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-3"><span className="text-[var(--text-muted)]">الرابط المطبع</span><p className="mt-1 truncate font-mono text-cyan-200" dir="ltr">{globalResult.normalized_url || globalResult.normalizedUrl || '—'}</p></div><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-3"><span className="text-[var(--text-muted)]">الحساب المنضم</span><p className="mt-1 font-bold">{globalResult.joined_by_account_id || '—'}</p></div><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-3"><span className="text-[var(--text-muted)]">المحاولات / التخطي</span><p className="mt-1 font-black">{globalResult.attempts || 0} / {globalResult.skipCount || 0}</p></div></div>}</section>

    <section className="rounded-3xl border border-orange-400/20 bg-orange-500/5 p-5 shadow-[var(--shadow-card)]"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-orange-300"><Users className="h-5 w-5" /><h2 className="text-lg font-black">مراجعة العضويات المكررة</h2></div><p className="mt-2 text-xs leading-6 text-[var(--text-muted)]">يفحص كل حساب JOIN_ROLE متصل، ويعرض المجموعات المشتركة. المعاينة لا تغيّر شيئًا؛ التنفيذ يخرج الحسابات الزائدة فقط بعد تأكيدك.</p></div><div className="flex flex-wrap items-center gap-2"><label className="text-xs font-bold">الاحتفاظ بحساب<select value={keepAccountId} onChange={event => setKeepAccountId(event.target.value)} className="mr-2 rounded-xl border border-[var(--border-default)] bg-[var(--bg-surface)] px-2 py-2 text-xs"><option value="">الأقدم تلقائيًا</option>{dashboard.joinAccounts.map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select></label><button type="button" onClick={reviewMemberships} disabled={membershipLoading} className="inline-flex items-center gap-2 rounded-xl border border-orange-400/30 px-4 py-2.5 text-xs font-black text-orange-200 disabled:opacity-50">{membershipLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}معاينة الآن</button><button type="button" onClick={cleanupMemberships} disabled={membershipLoading || !membershipReview?.duplicateGroups} className="inline-flex items-center gap-2 rounded-xl bg-orange-500 px-4 py-2.5 text-xs font-black text-slate-950 disabled:opacity-50"><Trash2 className="h-4 w-4" />تنظيف التكرارات</button></div></div>{membershipReview && <div className="mt-4 grid gap-3 md:grid-cols-4"><Metric label="حسابات مفحوصة" value={membershipReview.accountsScanned || 0} hint={`${membershipReview.accountsReady || 0} جاهزة`} icon={Users} tone="bg-cyan-400/10 text-cyan-300" /><Metric label="المجموعات" value={membershipReview.groupsFound || 0} hint="تم اكتشافها" icon={Link2} tone="bg-violet-400/10 text-violet-300" /><Metric label="مجموعات مكررة" value={membershipReview.duplicateGroups || 0} hint="تحتاج تنظيفًا" icon={AlertTriangle} tone="bg-orange-400/10 text-orange-300" /><Metric label="خرج منها" value={membershipReview.left || 0} hint={`${membershipReview.failed || 0} فشل`} icon={CheckCircle2} tone="bg-emerald-400/10 text-emerald-300" /></div>}{membershipReview?.groups?.filter((group: any) => group.duplicate).slice(0, 20).map((group: any) => <div key={group.groupId} className="mt-3 rounded-2xl border border-orange-400/20 bg-[var(--bg-surface)] p-3 text-xs"><div className="flex flex-wrap items-center justify-between gap-2"><span className="font-black">{group.title}</span><span className="text-orange-200">الاحتفاظ: {group.accounts.find((account: any) => String(account.accountId) === String(group.keepAccountId))?.accountName || group.keepAccountId}</span></div><p className="mt-2 text-[var(--text-muted)]">الحسابات المشتركة: {group.accounts.map((account: any) => `${account.accountName}${group.leaveAccountIds.includes(account.accountId) ? ' (سيخرج)' : ' (يُحتفظ به)'}`).join('، ')}</p></div>)}</section>

    <section className="grid gap-5 xl:grid-cols-2"><div className="rounded-3xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-5 shadow-[var(--shadow-card)]"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-cyan-300"><Search className="h-5 w-5" /><h2 className="text-lg font-black text-[var(--text-primary)]">البحث التلقائي عن روابط Telegram</h2></div><p className="mt-2 text-xs leading-6 text-[var(--text-muted)]">هذه الحسابات تقرأ الرسائل المسموح بها وتستخرج t.me فقط. التشغيل اليدوي يفحص السجل الحقيقي، والاستماع اللحظي يعمل طالما الحساب متصل.</p></div><button type="button" onClick={searchNow} disabled={working === 'search' || !selectedSearch.length} className="inline-flex items-center gap-2 rounded-xl bg-cyan-500 px-4 py-2.5 text-xs font-black text-slate-950 disabled:opacity-50">{working === 'search' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}فحص الآن</button></div><div className="mt-5 space-y-2">{dashboard.searchAccounts.length ? dashboard.searchAccounts.map(account => { const worker = workerFor(account.id); const active = worker?.status === 'running' && account.status === 'connected'; return <label key={account.id} className={cn('flex cursor-pointer items-center gap-3 rounded-2xl border p-3 transition', selectedSearch.includes(account.id) ? 'border-cyan-400/35 bg-cyan-400/5' : 'border-[var(--border-default)] bg-[var(--bg-surface)]')}><input type="checkbox" checked={selectedSearch.includes(account.id)} onChange={() => toggle(setSelectedSearch, account.id)} className="h-4 w-4 accent-cyan-500" /><span className={cn('rounded-xl p-2', active ? 'bg-emerald-400/10 text-emerald-300' : 'bg-slate-400/10 text-slate-300')}>{active ? <Wifi className="h-4 w-4" /> : <WifiOff className="h-4 w-4" />}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-bold">{account.name}</span><span className="mt-1 block text-[11px] text-[var(--text-muted)]">{account.phone_number || account.username || 'بدون معرف'} · آخر نشاط {ago(account.last_activity_at || worker?.lastCheck)}</span></span><Pill value={active ? 'SUCCESS' : account.status === 'connected' ? 'PROCESSING' : 'FAILED'} /></label>; }) : <div className="rounded-2xl border border-dashed border-[var(--border-default)] p-8 text-center text-sm text-[var(--text-muted)]">لا توجد حسابات SEARCH_ROLE. أضف حسابًا من Telegram ثم عيّن دوره هنا.</div>}</div><div className="mt-3 flex items-center justify-between text-[11px] text-[var(--text-muted)]"><span>{selectedSearch.length} محدد</span><button type="button" onClick={() => setSelectedSearch(selectedSearch.length === dashboard.searchAccounts.length ? [] : dashboard.searchAccounts.map(a => a.id))} className="font-bold text-cyan-300">{selectedSearch.length === dashboard.searchAccounts.length ? 'مسح التحديد' : 'تحديد الكل'}</button></div></div>

      <div className="rounded-3xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-5 shadow-[var(--shadow-card)]"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-violet-300"><UserRound className="h-5 w-5" /><h2 className="text-lg font-black text-[var(--text-primary)]">حسابات الانضمام</h2></div><p className="mt-2 text-xs leading-6 text-[var(--text-muted)]">حسابات JOIN_ROLE لا تستقبل مهام بحث. يجب أن تكون متصلة وذات Worker فعلي قبل دخولها إلى الطابور.</p></div><div className="flex items-center gap-2"><button type="button" onClick={() => setSelectedJoin(eligibleJoin.map(account => account.id))} disabled={!eligibleJoin.length} className="rounded-xl border border-violet-400/25 px-3 py-1.5 text-[11px] font-bold text-violet-200 disabled:cursor-not-allowed disabled:opacity-40">تحديد الجاهز</button><span className="rounded-full border border-violet-400/20 bg-violet-400/10 px-3 py-1.5 text-[11px] font-bold text-violet-200">{selectedJoin.length} محدد</span></div></div><div className="mt-5 space-y-2">{dashboard.joinAccounts.length ? dashboard.joinAccounts.map(account => { const worker = workerFor(account.id); const active = isJoinWorkerReady(account); return <label key={account.id} className={cn('flex items-center gap-3 rounded-2xl border p-3 transition', active ? 'cursor-pointer' : 'cursor-not-allowed opacity-70', selectedJoin.includes(account.id) ? 'border-violet-400/35 bg-violet-400/5' : 'border-[var(--border-default)] bg-[var(--bg-surface)]')}><input type="checkbox" disabled={!active} checked={selectedJoin.includes(account.id)} onChange={() => toggle(setSelectedJoin, account.id)} className="h-4 w-4 accent-violet-500" /><span className={cn('rounded-xl p-2', active ? 'bg-emerald-400/10 text-emerald-300' : 'bg-amber-400/10 text-amber-300')}>{active ? <Wifi className="h-4 w-4" /> : <WifiOff className="h-4 w-4" />}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-bold">{account.name}</span><span className="mt-1 block text-[11px] text-[var(--text-muted)]">{account.phone_number || account.username || 'بدون معرف'} · {account.operation_count || 0} عملية · {account.error_count || 0} أخطاء</span></span><Pill value={active ? 'SUCCESS' : account.status === 'connected' ? 'PROCESSING' : 'FAILED'} /></label>; }) : <div className="rounded-2xl border border-dashed border-[var(--border-default)] p-8 text-center text-sm text-[var(--text-muted)]">لا توجد حسابات JOIN_ROLE حتى الآن.</div>}</div></div></section>

    <section className="rounded-3xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-5 shadow-[var(--shadow-card)]"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-amber-300"><Link2 className="h-5 w-5" /><h2 className="text-lg font-black text-[var(--text-primary)]">الروابط المؤهلة للانضمام</h2></div><p className="mt-2 text-xs leading-6 text-[var(--text-muted)]">المعرف الموحد يمنع تكرار الرابط، وUnique Constraint يمنع إنشاء عمليتي انضمام لنفس الحساب والرابط.</p></div><div className="flex flex-wrap items-center gap-2"><label className="relative"><Search className="absolute right-3 top-2.5 h-4 w-4 text-[var(--text-muted)]" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث عن رابط أو مصدر" className="w-64 rounded-xl border border-[var(--border-default)] bg-[var(--bg-surface)] py-2.5 pr-9 pl-3 text-xs" dir="ltr" /></label><button type="button" onClick={() => setImportOpen(true)} className="inline-flex items-center gap-1 rounded-xl border border-emerald-400/25 px-3 py-2.5 text-xs font-bold text-emerald-300"><Upload className="h-3.5 w-3.5" />استيراد</button><button type="button" onClick={() => exportData('links')} className="inline-flex items-center gap-1 rounded-xl border border-indigo-400/25 px-3 py-2.5 text-xs font-bold text-indigo-300"><Download className="h-3.5 w-3.5" />تصدير</button><button type="button" onClick={() => setSelectedLinks(selectedLinks.length === filteredLinks.length ? [] : filteredLinks.map(link => link.id))} className="rounded-xl border border-cyan-400/25 px-3 py-2.5 text-xs font-bold text-cyan-300">{selectedLinks.length === filteredLinks.length && filteredLinks.length ? 'مسح الكل' : `تحديد ${filteredLinks.length}`}</button><button type="button" onClick={deleteAllLinks} disabled={working === 'links:all' || !Number(dashboard.stats?.total || 0)} className="inline-flex items-center gap-1 rounded-xl border border-rose-400/30 px-3 py-2.5 text-xs font-bold text-rose-300 hover:bg-rose-400/10 disabled:cursor-not-allowed disabled:opacity-40">{working === 'links:all' ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Trash2 className="h-3.5 w-3.5" />}حذف الكل</button></div></div><div className="mt-4 overflow-x-auto rounded-2xl border border-[var(--border-default)]"><table className="w-full min-w-[900px] text-right text-xs"><thead className="bg-[var(--bg-surface)] text-[var(--text-muted)]"><tr><th className="p-3"><input type="checkbox" checked={Boolean(filteredLinks.length && selectedLinks.length === filteredLinks.length)} onChange={() => setSelectedLinks(selectedLinks.length === filteredLinks.length ? [] : filteredLinks.map(link => link.id))} className="h-4 w-4 accent-cyan-500" /></th><th className="p-3">الرابط</th><th className="p-3">النوع</th><th className="p-3">المصدر</th><th className="p-3">الحالة</th><th className="p-3">آخر ظهور</th><th className="p-3">إجراء</th></tr></thead><tbody>{loading ? <tr><td colSpan={7} className="p-10 text-center"><Loader2 className="mx-auto h-6 w-6 animate-spin text-cyan-300" /></td></tr> : filteredLinks.length ? filteredLinks.map(link => <tr key={link.id} className="border-t border-[var(--border-default)]"><td className="p-3"><input type="checkbox" checked={selectedLinks.includes(link.id)} onChange={() => toggle(setSelectedLinks, link.id)} className="h-4 w-4 accent-cyan-500" /></td><td className="max-w-[310px] p-3"><a href={link.normalized_url} target="_blank" rel="noreferrer" className="flex items-center gap-2 truncate font-mono text-cyan-300 hover:underline" dir="ltr">{link.normalized_url}<ExternalLink className="h-3.5 w-3.5 shrink-0" /></a><span className="mt-1 block text-[10px] text-[var(--text-muted)]">{link.telegram_identifier || '—'} · {date(link.first_seen_at)}</span></td><td className="p-3">{link.link_type === 'PRIVATE_INVITE' ? 'دعوة خاصة' : 'عام'}</td><td className="p-3">{link.source_account_name || '—'}</td><td className="p-3"><Pill value={link.status} /></td><td className="p-3 whitespace-nowrap">{ago(link.last_seen_at)}</td><td className="p-3"><button type="button" title="حذف الرابط" aria-label="حذف الرابط" onClick={() => deleteLink(link.id)} disabled={working === `link:${link.id}`} className="rounded-lg p-2 text-rose-300 hover:bg-rose-400/10 disabled:cursor-not-allowed disabled:opacity-50"><Trash2 className="h-4 w-4" /></button></td></tr>) : <tr><td colSpan={7} className="p-12 text-center text-sm text-[var(--text-muted)]">لم تُكتشف روابط بعد. فعّل حساب SEARCH_ROLE ثم اضغط فحص الآن.</td></tr>}</tbody></table></div><div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-xs text-[var(--text-muted)]"><span>صفحة {page} من {totalPages} · يتم البحث والتصفية داخل PostgreSQL</span><div className="flex items-center gap-1"><button type="button" disabled={page <= 1} onClick={() => setPage(value => Math.max(1, value - 1))} className="rounded-lg border border-[var(--border-default)] p-2 disabled:opacity-40"><ChevronRight className="h-4 w-4" /></button><button type="button" disabled={page >= totalPages} onClick={() => setPage(value => Math.min(totalPages, value + 1))} className="rounded-lg border border-[var(--border-default)] p-2 disabled:opacity-40"><ChevronLeft className="h-4 w-4" /></button></div><div className="flex gap-1"><button type="button" onClick={() => exportData('operations')} className="rounded-lg border border-[var(--border-default)] px-2 py-1.5">تصدير العمليات</button><button type="button" onClick={() => exportData('jobs')} className="rounded-lg border border-[var(--border-default)] px-2 py-1.5">تصدير المهام</button><button type="button" onClick={() => exportData('events')} className="rounded-lg border border-[var(--border-default)] px-2 py-1.5">تصدير الأحداث</button></div></div></section>

    <section className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><div className="rounded-3xl border border-violet-400/20 bg-violet-500/5 p-5 shadow-[var(--shadow-card)]"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-violet-200"><ShieldCheck className="h-5 w-5" /><h2 className="text-lg font-black">إنشاء مهمة انضمام حقيقية</h2></div><p className="mt-2 text-xs leading-6 text-violet-100/65">سيتم تنفيذ كل علاقة حساب × رابط مرة واحدة فقط. التأخير يستخدم لتوزيع الحمل واحترام الحدود، وليس للتحايل على أنظمة مكافحة الإساءة.</p></div><div className="flex flex-wrap gap-2"><button type="button" onClick={() => createJob(false)} disabled={working === 'job'} className="inline-flex items-center gap-2 rounded-xl bg-violet-500 px-4 py-2.5 text-xs font-black text-white disabled:opacity-50">{working === 'job' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}بدء المحدد</button><button type="button" onClick={() => createJob(true)} disabled={working === 'job' || !Number(dashboard.stats?.pending || 0)} className="inline-flex items-center gap-2 rounded-xl border border-emerald-400/30 bg-emerald-400/10 px-4 py-2.5 text-xs font-black text-emerald-200 disabled:opacity-40">{working === 'job' ? <Loader2 className="h-4 w-4" /> : <CheckCircle2 className="h-4 w-4" />}إنشاء مهمة لكل {dashboard.stats?.pending || 0} جاهز</button></div></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label className="text-xs text-violet-100/70">الفاصل الأدنى (ث)<input type="number" min={30} value={minDelay} onChange={event => setMinDelay(Number(event.target.value))} className="mt-2 w-full rounded-xl border border-violet-300/20 bg-black/10 px-3 py-2 text-sm text-white" /></label><label className="text-xs text-violet-100/70">الفاصل الأقصى (ث)<input type="number" min={30} value={maxDelay} onChange={event => setMaxDelay(Number(event.target.value))} className="mt-2 w-full rounded-xl border border-violet-300/20 bg-black/10 px-3 py-2 text-sm text-white" /></label><label className="text-xs text-violet-100/70">إعادات محدودة<select value={maxRetries} onChange={event => setMaxRetries(Number(event.target.value))} className="mt-2 w-full rounded-xl border border-violet-300/20 bg-black/10 px-3 py-2 text-sm text-white"><option value={0}>بدون إعادة</option><option value={1}>إعادة واحدة</option><option value={2}>إعادتان</option></select></label><label className="text-xs text-violet-100/70">طريقة التوزيع<select value={strategy} onChange={event => setStrategy(event.target.value)} className="mt-2 w-full rounded-xl border border-violet-300/20 bg-black/10 px-3 py-2 text-sm text-white"><option value="smart">ذكي وآمن</option><option value="least_loaded">الأقل حملًا</option><option value="round_robin">دوري</option></select></label></div><div className="mt-4 flex flex-wrap gap-2 text-[11px] text-violet-100/70"><span className="rounded-full bg-black/10 px-3 py-1.5">{selectedJoin.length} حساب</span><span className="rounded-full bg-black/10 px-3 py-1.5">{selectedLinks.length} رابط</span><span className="rounded-full bg-black/10 px-3 py-1.5">Queue: telegram-join-automation</span><span className="rounded-full bg-black/10 px-3 py-1.5">Idempotency + DB Lock</span><span className="rounded-full bg-black/10 px-3 py-1.5">{settingsSaveState === 'saving' ? 'جارٍ حفظ الإعدادات…' : settingsSaveState === 'saved' ? 'تم حفظ الإعدادات تلقائياً' : settingsSaveState === 'error' ? 'تعذر حفظ الإعدادات' : 'الإعدادات محفوظة'}</span></div></div>

      <div className="rounded-3xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-5 shadow-[var(--shadow-card)]"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-sky-300"><Activity className="h-5 w-5" /><h2 className="text-lg font-black">المهمة الحالية</h2></div><p className="mt-2 text-xs text-[var(--text-muted)]">تحديث مستمر من قاعدة البيانات، مع تسجيل كل نتيجة فعلية من Telegram.</p></div>{activeJobId && <div className="flex gap-1"><button type="button" title="إيقاف مؤقت" onClick={() => controlJob('PAUSED')} disabled={working?.startsWith('job:')} className="rounded-lg p-2 text-amber-300 hover:bg-amber-400/10 disabled:opacity-50"><Pause className="h-4 w-4" /></button><button type="button" title="استئناف" onClick={() => controlJob('RUNNING')} disabled={working?.startsWith('job:')} className="rounded-lg p-2 text-emerald-300 hover:bg-emerald-400/10 disabled:opacity-50"><Play className="h-4 w-4" /></button><button type="button" title="إيقاف نهائي" onClick={() => controlJob('STOPPED')} disabled={working?.startsWith('job:')} className="rounded-lg p-2 text-rose-300 hover:bg-rose-400/10 disabled:opacity-50"><Square className="h-4 w-4" /></button></div>}</div>{job?.job ? <><div className="mt-4 flex items-center justify-between text-xs"><span className="font-mono text-[var(--text-muted)]">{job.job.id}</span><Pill value={job.job.status} /></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[var(--bg-surface)]"><div className="h-full rounded-full bg-violet-400 transition-all" style={{ width: `${job.progress || 0}%` }} /></div><div className="mt-2 flex flex-wrap justify-between gap-2 text-[11px] text-[var(--text-muted)]"><span>{job.progress || 0}% مكتمل</span><span>إجمالي المهمة: <strong className="text-violet-200">{job.job.total_count || job.stats?.total || 0}</strong></span><span>المتبقي: <strong className="text-amber-200">{job.stats?.pending || 0}</strong></span></div><div className="mt-4 grid grid-cols-3 gap-2 text-center text-[11px]"><div className="rounded-xl bg-[var(--bg-surface)] p-2"><strong className="block text-emerald-300">{job.stats?.success || 0}</strong>نجاح</div><div className="rounded-xl bg-[var(--bg-surface)] p-2"><strong className="block text-rose-300">{job.stats?.failed || 0}</strong>فشل</div><div className="rounded-xl bg-[var(--bg-surface)] p-2"><strong className="block text-amber-300">{job.stats?.skipped || 0}</strong>تخطي</div></div></> : <div className="flex min-h-[170px] flex-col items-center justify-center rounded-2xl border border-dashed border-[var(--border-default)] text-center"><Bot className="h-7 w-7 text-[var(--text-muted)]" /><p className="mt-3 text-sm font-bold">لا توجد مهمة محددة</p><p className="mt-1 text-xs text-[var(--text-muted)]">أنشئ مهمة بعد تحديد حسابات الانضمام والروابط.</p></div>}</div></section>

    <section className="rounded-3xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-5 shadow-[var(--shadow-card)]"><div className="flex items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-emerald-300"><Activity className="h-5 w-5" /><h2 className="text-lg font-black">سجل النشاط اللحظي</h2></div><p className="mt-2 text-xs text-[var(--text-muted)]">لا تظهر حالة نجاح إلا بعد حفظ نتيجة من طبقة تنفيذ Telegram.</p></div><button type="button" onClick={() => { fetchDashboard(); fetchJob(); }} className="inline-flex items-center gap-2 rounded-xl border border-[var(--border-default)] px-3 py-2 text-xs font-bold text-[var(--text-secondary)]"><RefreshCw className="h-4 w-4" />تحديث</button></div><div className="mt-4 grid gap-2 md:grid-cols-2 xl:grid-cols-3">{dashboard.events.length ? dashboard.events.slice(0, 12).map((event, index) => <div key={event.id || index} className="flex items-start gap-3 rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-3"><span className={cn('mt-0.5 rounded-lg p-1.5', event.event_type.includes('failed') ? 'bg-rose-400/10 text-rose-300' : event.event_type.includes('completed') ? 'bg-emerald-400/10 text-emerald-300' : 'bg-cyan-400/10 text-cyan-300')}><Activity className="h-3.5 w-3.5" /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{eventLabel[event.event_type] || event.event_type}</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">{date(event.created_at)} · {event.status || 'تحديث محفوظ'}</p></div></div>) : <div className="col-span-full rounded-2xl border border-dashed border-[var(--border-default)] p-8 text-center text-sm text-[var(--text-muted)]">ستظهر الأحداث هنا فور اكتشاف رابط أو بدء عملية حقيقية.</div>}</div></section>

    <section className="rounded-3xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-5 shadow-[var(--shadow-card)]"><div className="flex items-center gap-2 text-orange-300"><Users className="h-5 w-5" /><h2 className="text-lg font-black">إدارة أدوار الحسابات</h2></div><p className="mt-2 text-xs leading-6 text-[var(--text-muted)]">يمكن تبديل الدور من الخادم فقط. تغيير الدور لا يكشف الجلسة ولا يرسل Session Data إلى الواجهة.</p><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{dashboard.accounts.map(account => <div key={account.id} className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-sm font-black">{account.name}</p><p className="mt-1 truncate font-mono text-[10px] text-[var(--text-muted)]" dir="ltr">{account.username ? `@${account.username}` : account.phone_number || account.id}</p></div><Pill value={account.status === 'connected' ? 'SUCCESS' : 'FAILED'} /></div><div className="mt-3 flex items-center justify-between gap-2"><span className="text-[11px] font-bold text-cyan-200">{roleLabel[account.automation_role]}</span><select value={account.automation_role} disabled={working === `role:${account.id}`} onChange={event => changeRole(account, event.target.value as Account['automation_role'])} className="rounded-lg border border-[var(--border-default)] bg-[var(--bg-elevated)] px-2 py-1.5 text-[11px]"><option value="SEARCH_ROLE">بحث فقط</option><option value="JOIN_ROLE">انضمام فقط</option></select></div><div className="mt-2 flex flex-wrap items-center gap-2 text-[10px] text-[var(--text-muted)]"><span>Worker: {statusLabel(account.worker_state)}</span><span>Connection: {statusLabel(account.connection_state)}</span><span>Heartbeat: {ago(account.last_heartbeat_at)}</span><span>Last op: {ago(account.last_operation_at)}</span></div>{account.last_error && <p className="mt-3 rounded-xl bg-rose-400/5 p-2 text-[10px] leading-5 text-rose-200">{account.last_error}</p>}</div>)}</div></section>
    {importOpen && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-2xl rounded-3xl border border-emerald-400/20 bg-[var(--bg-elevated)] p-5 shadow-2xl"><div className="flex items-center justify-between"><div><h2 className="text-lg font-black">استيراد روابط Telegram</h2><p className="mt-1 text-xs text-[var(--text-muted)]">كل سطر رابط عام أو دعوة خاصة. سيُحفظ الاستيراد كمصدر بحث ولا ينفذ انضمامًا تلقائيًا.</p></div><button type="button" onClick={() => setImportOpen(false)} className="rounded-lg p-2 text-[var(--text-muted)] hover:bg-[var(--bg-surface)]"><X className="h-4 w-4" /></button></div><label className="mt-5 block text-xs font-bold">حساب المصدر<select value={importSource} onChange={event => setImportSource(event.target.value)} className="mt-2 w-full rounded-xl border border-[var(--border-default)] bg-[var(--bg-surface)] px-3 py-2.5 text-sm"><option value="">اختر SEARCH_ROLE</option>{eligibleSearch.map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select></label><label className="mt-4 block text-xs font-bold">الروابط<textarea value={importContent} onChange={event => setImportContent(event.target.value)} rows={8} placeholder="https://t.me/example\nhttps://t.me/+inviteHash" dir="ltr" className="mt-2 w-full rounded-xl border border-[var(--border-default)] bg-[var(--bg-surface)] p-3 font-mono text-sm" /></label><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={() => setImportOpen(false)} className="rounded-xl border border-[var(--border-default)] px-4 py-2.5 text-xs font-bold">إلغاء</button><button type="button" onClick={importLinks} disabled={working === 'import'} className="inline-flex items-center gap-2 rounded-xl bg-emerald-500 px-4 py-2.5 text-xs font-black text-slate-950 disabled:opacity-50">{working === 'import' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}استيراد الآن</button></div></div></div>}
  </main>;
}
